
import json
import os
import smtplib
import ssl
from email.message import EmailMessage


def main():
    # Read the test report generated by GitHub Actions
    with open("test-report.json", "r", encoding="utf-8") as file:
        report = json.load(file)

    smtp_server = os.environ["SMTP_SERVER"]
    smtp_port = int(os.environ["SMTP_PORT"])
    smtp_username = os.environ["SMTP_USERNAME"]
    smtp_password = os.environ["SMTP_PASSWORD"]
    recipient = os.environ["REPORT_EMAIL_TO"]

    status = report["status"].upper()
    commit = report["commit_sha"]

    message = EmailMessage()
    message["Subject"] = f"[{status}] DevOps Test Report - {commit[:7]}"
    message["From"] = smtp_username
    message["To"] = recipient

    lines = [
        "DevOps Assignment Portal - Automated Test Report",
        "",
        f"Repository: {report['repository']}",
        f"Branch: {report['branch']}",
        f"Commit SHA: {commit}",
        f"Pipeline Run ID: {report['run_id']}",
        f"Timestamp: {report['timestamp']}",
        "",
        f"Overall Status: {status}",
        f"Total Tests: {report['total']}",
        f"Passed: {report['passed']}",
        f"Failed: {report['failed']}",
        f"Skipped: {report.get('skipped', 0)}",
        "",
        "Individual Test Results:"
    ]

    for test in report["tests"]:
        lines.append(f"- {test['name']}: {test['result'].upper()}")

        if test.get("failure_message"):
            lines.append(f"  Failure: {test['failure_message']}")

    message.set_content("\n".join(lines))

    # Attach the complete JSON report
    with open("test-report.json", "rb") as file:
        message.add_attachment(
            file.read(),
            maintype="application",
            subtype="json",
            filename="test-report.json"
        )

    # Send email securely using Gmail SMTP
    context = ssl.create_default_context()

    with smtplib.SMTP_SSL(
        smtp_server, smtp_port, context=context
    ) as server:
        server.login(smtp_username, smtp_password)
        server.send_message(message)

    print("Email report sent successfully!")


if __name__ == "__main__":
    main()
